<script setup>
import {computed,onMounted} from 'vue';
import {BookOpenCheck,LibraryBig,Clock3,CircleCheck,Plus,ChartNoAxesCombined,ArrowRight,RefreshCw,ShieldCheck} from 'lucide-vue-next';
import {useAuthStore} from '~/stores/api/auth';
import {useTutorDashboardStore} from '~/stores/api/tutorDashboard';
const auth=useAuthStore(),store=useTutorDashboardStore();
const name=computed(()=>auth.user?.nama?.split(' ')[0]||'Tutor');
const cards=computed(()=>[
  {label:'Total Soal',value:store.summary?.total_questions,icon:BookOpenCheck,bg:'bg-pale-blue',text:'text-primary-container'},
  {label:'Total Materi',value:store.summary?.total_materials,icon:LibraryBig,bg:'bg-accent-purple-soft',text:'text-accent-purple'},
  {label:'Menunggu Review',value:store.summary?.pending_review,icon:Clock3,bg:'bg-soft-orange',text:'text-on-secondary-container'},
  {label:'Konten Aktif',value:store.summary?.active_content,icon:CircleCheck,bg:'bg-success-soft',text:'text-success-emerald'},
]);
const statusItems=computed(()=>[
  {label:'Approved',value:store.summary?.active_content||0,tone:'bg-success-emerald'},
  {label:'Pending Review',value:store.summary?.pending_review||0,tone:'bg-bright-orange'},
  {label:'Rejected',value:store.summary?.rejected_content||0,tone:'bg-danger-rose'},
  {label:'Draft',value:store.summary?.draft_content||0,tone:'bg-primary-container'},
]);
const statusLabel={draft:'Draft',review:'Menunggu Review',active:'Aktif',rejected:'Ditolak'};
const actions=[{label:'Tambah Soal',path:'/my-questions/create',icon:BookOpenCheck},{label:'Tambah Materi',path:'/my-materials/create',icon:LibraryBig},{label:'Lihat Status Moderasi',path:'/my-moderation',icon:ShieldCheck},{label:'Lihat Analytics',path:'/tutor-analytics',icon:ChartNoAxesCombined}];
function date(value){return value?new Date(value).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}):'—';}
onMounted(()=>store.fetchTutorDashboard());
</script>
<template>
  <div class="mx-auto flex w-full max-w-[1536px] min-w-0 flex-col gap-6 px-4 pb-8 pt-2 sm:px-6 lg:px-8 lg:pb-10">
    <section class="relative overflow-hidden rounded-3xl bg-gradient-to-br from-primary-container to-deep-blue px-6 py-7 shadow-sm sm:px-8 sm:py-8"><div class="pointer-events-none absolute -right-12 -top-20 h-64 w-64 rounded-full bg-white/10 blur-2xl"/><div class="relative flex min-h-[150px] items-center justify-between gap-4"><div class="max-w-2xl"><span class="mb-3 inline-flex items-center gap-1.5 rounded-full bg-white/15 px-3 py-1 font-caption text-caption font-bold text-white"><ShieldCheck class="h-4 w-4"/>Tutor MatrIQ</span><h1 class="font-headline-md text-headline-md text-white">Selamat datang, {{ name }} 👋</h1><p class="mt-2 max-w-xl font-body-sm text-body-sm text-white/80">Kelola kontribusi materi dan soalmu hari ini.</p></div><img src="/mascot/duduk-bg.svg" alt="Maskot MatrIQ" class="hidden h-[150px] w-[150px] object-contain sm:block"/></div></section>
    <div v-if="store.error" role="alert" class="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-soft-blue bg-surface-white p-4"><span>{{ store.error }}</span><button class="inline-flex items-center gap-2 text-primary-container" @click="store.fetchTutorDashboard()"><RefreshCw class="h-4 w-4"/>Coba Lagi</button></div>
    <section aria-label="Ringkasan kontribusi" class="grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-4"><article v-for="card in cards" :key="card.label" class="rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-5"><div class="mb-3 flex h-11 w-11 items-center justify-center rounded-xl" :class="[card.bg,card.text]"><component :is="card.icon" class="h-5 w-5"/></div><p class="font-caption text-caption text-outline">{{ card.label }}</p><div v-if="store.isLoading" class="mt-2 h-8 w-16 animate-pulse rounded-lg bg-surface-container"/><strong v-else class="font-headline-md text-headline-md text-on-surface">{{ card.value ?? '—' }}</strong></article></section>
    <div class="grid min-w-0 gap-5 xl:grid-cols-[minmax(0,2fr)_minmax(280px,1fr)]"><div class="min-w-0 space-y-5"><section class="rounded-3xl border border-soft-blue bg-surface-white p-5 shadow-sm"><h2 class="mb-4 font-title-md text-title-md text-on-surface">Status Kontribusi</h2><div v-if="store.isLoading" class="h-24 animate-pulse rounded-2xl bg-surface-container"/><div v-else class="grid gap-3 sm:grid-cols-2"><div v-for="item in statusItems" :key="item.label" class="rounded-2xl bg-surface-container-low p-3"><div class="mb-2 flex items-center justify-between text-sm"><span>{{ item.label }}</span><strong>{{ item.value }}</strong></div><div class="h-1.5 overflow-hidden rounded-full bg-surface-container"><div class="h-full rounded-full" :class="item.tone" :style="{width:`${Math.round(100*item.value/Math.max(1,(store.summary?.total_questions||0)+(store.summary?.total_materials||0)))}%`}"/></div></div></div></section><section class="rounded-3xl border border-soft-blue bg-surface-white p-5 shadow-sm"><div class="mb-4 flex items-center justify-between"><h2 class="font-title-md text-title-md">Konten Terbaru</h2><NuxtLink to="/my-questions" class="text-sm text-primary-container">Lihat Semua <ArrowRight class="inline h-4 w-4"/></NuxtLink></div><div v-if="store.isLoading" class="space-y-2"><div v-for="n in 3" :key="n" class="h-16 animate-pulse rounded-2xl bg-surface-container"/></div><div v-else-if="!store.recentContent.length" class="rounded-2xl bg-surface-container-low p-6 text-center"><p class="font-label-md text-label-md">Belum ada kontribusi</p><p class="mt-1 text-sm text-on-surface-variant">Mulai buat soal atau materi pertamamu di MatrIQ.</p><div class="mt-4 flex justify-center gap-2"><NuxtLink to="/my-questions/create" class="rounded-xl bg-primary-container px-3 py-2 text-sm text-white">Tambah Soal</NuxtLink><NuxtLink to="/my-materials/create" class="rounded-xl border border-primary-container px-3 py-2 text-sm text-primary-container">Tambah Materi</NuxtLink></div></div><div v-else class="space-y-2"><div v-for="item in store.recentContent" :key="`${item.type}-${item.id}`" class="flex min-w-0 items-center gap-3 rounded-2xl border border-soft-blue p-3"><span class="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-pale-blue text-primary-container"><component :is="item.type==='Soal'?BookOpenCheck:LibraryBig" class="h-4 w-4"/></span><div class="min-w-0 flex-1"><p class="truncate text-sm font-semibold">{{ item.title }}</p><p class="text-xs text-on-surface-variant">{{ item.type }} · {{ date(item.created_at) }}</p></div><span class="shrink-0 text-xs text-primary-container">{{ statusLabel[item.status] || item.status }}</span></div></div></section></div><aside class="min-w-0 space-y-5"><section class="rounded-3xl border border-soft-blue bg-surface-white p-5 shadow-sm"><h2 class="mb-4 font-title-md text-title-md">Aksi Cepat</h2><div class="space-y-2"><NuxtLink v-for="action in actions" :key="action.path" :to="action.path" class="flex items-center gap-3 rounded-2xl border border-soft-blue p-3 text-sm hover:bg-pale-blue"><component :is="action.icon" class="h-4 w-4 text-primary-container"/><span class="flex-1">{{ action.label }}</span><ArrowRight class="h-4 w-4 text-primary-container"/></NuxtLink></div></section><section class="rounded-3xl border border-soft-blue bg-surface-white p-5 shadow-sm"><h2 class="mb-4 font-title-md text-title-md">Moderasi Terbaru</h2><p v-if="!store.recentModeration.length" class="text-sm text-on-surface-variant">Belum ada hasil moderasi.</p><div v-else class="space-y-3"><div v-for="item in store.recentModeration" :key="item.id" class="rounded-2xl bg-surface-container-low p-3"><p class="line-clamp-2 text-sm font-semibold">{{ item.title }}</p><p class="mt-1 text-xs text-on-surface-variant">{{ statusLabel[item.status] }} · {{ date(item.reviewed_at) }}</p><p v-if="item.status==='rejected'&&item.rejection_reason" class="mt-2 line-clamp-2 text-xs text-danger-rose">{{ item.rejection_reason }}</p></div></div></section></aside></div>
  </div>
</template>
